/* ================================================================
 * Inline rendering helpers
 * ================================================================ */

/* Returns the pixel width of a string rendered at the given size. */
static inline int FontTextWidth(const char *s, FontSize size)
{
    return (int)strlen(s) * g_fontMetrics[(int)size].cw;
}

/* Returns the cell height for a given size. */
static inline int FontCellHeight(FontSize size)
{
    return g_fontMetrics[(int)size].ch;
}

/* Draw a single character; returns the advance width in pixels. */
static inline int FontDrawChar(SDL_Renderer *ren, int x, int y, char c,
                               SDL_Color col, FontSize size)
{
    int idx = (unsigned char)c - 32;
    const FontMetrics *m = &g_fontMetrics[(int)size];
    const uint8_t (*glyphs)[m->ch][m->bytesPerRow];  /* VLA-ptr trick */
    if (idx < 0 || idx >= 95) idx = 0;  /* clamp to printable range */

    switch (size) {
        case FONT_SM: glyphs = g_fontGlyphs_SM; break;
        case FONT_MD: glyphs = g_fontGlyphs_MD; break;
        case FONT_LG: glyphs = g_fontGlyphs_LG; break;
        case FONT_MONO: glyphs = g_fontGlyphs_MONO; break;
        default: glyphs = g_fontGlyphs_SM; break;
    }

    SDL_SetRenderDrawColor(ren, col.r, col.g, col.b, col.a);
    for (int row = 0; row < m->ch; ++row) {
        for (int byte_i = 0; byte_i < m->bytesPerRow; ++byte_i) {
            uint8_t byte_val = glyphs[idx][row][byte_i];
            for (int bit = 7; bit >= 0; --bit) {
                int col_px = byte_i * 8 + (7 - bit);
                if (col_px >= m->cw) break;
                if (byte_val & (uint8_t)(1u << (unsigned)bit)) {
                    SDL_RenderDrawPoint(ren, x + col_px, y + row);
                }
            }
        }
    }
    return m->cw;
}

/* Draw a null-terminated string; returns the final x position. */
static inline int FontDrawText(SDL_Renderer *ren, int x, int y, const char *s,
                               SDL_Color col, FontSize size)
{
    if (!s) return x;
    int curX = x;
    int startX = x;
    FontMetrics m = FontMetricsFor(size);
    while (*s) {
        if (*s == '\n') {
            y += m.ch + 2;
            curX = startX;
        } else {
            FontDrawChar(ren, curX, y, *s, col, size);
            curX += m.cw;
        }
        s++;
    }
    return curX;
}

/* Backwards compatibility */
#define FONT_CHAR_W 7
#define FONT_CHAR_H 14

static inline void DrawChar(SDL_Renderer *ren, int x, int y, char c, SDL_Color col, int scale) {
    FontSize sz = (scale >= 2) ? FONT_LG : FONT_SM;
    FontDrawChar(ren, x, y, c, col, sz);
}

static inline void DrawText(SDL_Renderer *ren, int x, int y, const char *str, SDL_Color col, int scale) {
    FontSize sz = (scale >= 2) ? FONT_LG : FONT_SM;
    FontDrawText(ren, x, y, str, col, sz);
}

#endif /* PLUTUS_FONT_H */
